/* Popup manners — generated by sitereal. A hand edit here is kept: sitereal asks before writing over it. */
(function () {
  if (document.__siterealPopup) return;
  document.__siterealPopup = true;

  var FOCUSABLE = 'a[href],area[href],button:not([disabled]),input:not([disabled]):not([type="hidden"]),select:not([disabled]),textarea:not([disabled]),iframe,[tabindex]:not([tabindex="-1"]),[contenteditable="true"]';

  /* Inside a quoted attribute value, not an identifier: CSS.escape is the
     wrong tool here and would mangle the id. */
  function q(s) { return String(s).replace(/(["\\])/g, '\\$1'); }
  function triggersOf(panel) { return document.querySelectorAll('[popovertarget="' + q(panel.id) + '"]'); }
  function panelOf(trigger) {
    var id = trigger.getAttribute('popovertarget');
    return id ? document.getElementById(id) : null;
  }
  function isOpen(panel) { return panel.matches(':popover-open'); }

  /* The one question every opening asks first: is this popup for this screen?
     The answer is in the panel's own stylesheet, so moving the breakpoint is
     moving a media query and nothing here. */
  function allowed(panel) {
    return getComputedStyle(panel).getPropertyValue('--popup-on').trim() !== '0';
  }

  function show(panel) { if (allowed(panel)) { try { if (!isOpen(panel)) panel.showPopover(); } catch (e) {} } }
  function hide(panel) { try { if (isOpen(panel)) panel.hidePopover(); } catch (e) {} }

  /* ---- shown once ------------------------------------------------------ */

  function store(panel) {
    var mode = panel.getAttribute('data-popup-once');
    if (!mode) return null;
    try { return mode === 'ever' ? window.localStorage : window.sessionStorage; } catch (e) { return null; }
  }
  function seen(panel) {
    var s = store(panel);
    try { return !!s && s.getItem('sitereal:popup:' + panel.id) === '1'; } catch (e) { return false; }
  }
  function markSeen(panel) {
    var s = store(panel);
    try { if (s) s.setItem('sitereal:popup:' + panel.id, '1'); } catch (e) {}
  }
  /* Only what opened by itself is remembered. Somebody pressing a button is
     asking for it, and an ask is answered however many times it is made. */
  function auto(panel) {
    if (seen(panel) || !allowed(panel)) return;
    markSeen(panel);
    show(panel);
  }

  /* ---- placing a trigger popup ----------------------------------------- */

  function anchored(panel) {
    var cs = getComputedStyle(panel);
    var a = cs.positionAnchor, area = cs.positionArea;
    return !!(a && a !== 'none' && a !== 'auto') || !!(area && area !== 'none');
  }

  function place(panel) {
    var trigger = panel.__from || triggersOf(panel)[0];
    if (!trigger || !trigger.isConnected) return;
    var t = trigger.getBoundingClientRect();
    var gap = 8;
    /* Measured after it is open, because a popover has no size until then. */
    var w = panel.offsetWidth, h = panel.offsetHeight;
    var left = t.left;
    var top = t.bottom + gap;
    /* Flip and nudge rather than hang off the edge: a panel you have to scroll
       the page sideways to read is a panel that didn't open. */
    if (left + w > window.innerWidth - gap) left = Math.max(gap, t.right - w);
    if (top + h > window.innerHeight - gap && t.top - gap - h > 0) top = t.top - gap - h;
    panel.style.insetInlineStart = Math.round(left) + 'px';
    panel.style.insetBlockStart = Math.round(top) + 'px';
    panel.style.insetInlineEnd = 'auto';
    panel.style.insetBlockEnd = 'auto';
  }

  function follow(panel) {
    var again = function () { if (isOpen(panel)) place(panel); else stop(); };
    var stop = function () {
      window.removeEventListener('scroll', again, true);
      window.removeEventListener('resize', again);
    };
    window.addEventListener('scroll', again, true);
    window.addEventListener('resize', again);
  }

  /* ---- blocking the page ----------------------------------------------- */

  var inertOk = 'inert' in HTMLElement.prototype;

  /* What a blocking panel holds while it is drawn: the rest of the page
     inert, the page's own scroll held still, and Tab going round inside the
     panel. Inert is every neighbour at every level up to the body — a panel
     placed in the page, a card's own profile say, has neighbours in its
     section and in <main>, and making only the body's other children inert
     left all of those reachable. */
  var locks = 0;
  function isolate(panel) {
    if (!inertOk) return function () {};
    var marked = [];
    for (var at = panel; at.parentElement; at = at.parentElement) {
      var kids = at.parentElement.children;
      for (var i = 0; i < kids.length; i++) {
        var kid = kids[i];
        if (kid === at || kid.inert || kid.tagName === 'SCRIPT' || kid.tagName === 'STYLE') continue;
        kid.inert = true;
        marked.push(kid);
      }
      if (at.parentElement === document.body) break;
    }
    panel.setAttribute('aria-modal', 'true');
    /* The scroll lock is a rule of the part defaults (`[data-popup-locked]`
       on <html>), so a stylesheet of yours can still say otherwise; counted,
       since one blocking panel can open over another. */
    locks += 1;
    document.documentElement.setAttribute('data-popup-locked', '');
    var untrap = trapTab(panel);
    return function () {
      for (var j = 0; j < marked.length; j++) marked[j].inert = false;
      panel.removeAttribute('aria-modal');
      untrap();
      locks = Math.max(0, locks - 1);
      if (!locks) document.documentElement.removeAttribute('data-popup-locked');
    };
  }

  /* Tab past the last thing in the panel comes back to its first, and
     Shift+Tab the other way — the dialog pattern's keyboard. With the page
     inert it would otherwise leave for the browser's own toolbar. Only what
     can be seen counts: a panel that shows one record of many hides the rest. */
  function tabbable(panel) {
    return [].filter.call(panel.querySelectorAll(FOCUSABLE), function (el) {
      return el.getClientRects().length > 0 && getComputedStyle(el).visibility !== 'hidden';
    });
  }
  function trapTab(panel) {
    var onKey = function (e) {
      if (e.key !== 'Tab' || e.defaultPrevented || !isOpen(panel)) return;
      var items = tabbable(panel);
      var at = document.activeElement;
      if (!items.length) { e.preventDefault(); panel.focus(); return; }
      var first = items[0], last = items[items.length - 1];
      if (e.shiftKey ? (at === first || !panel.contains(at)) : (at === last || !panel.contains(at))) {
        e.preventDefault();
        (e.shiftKey ? last : first).focus();
      }
    };
    document.addEventListener('keydown', onKey, true);
    return function () { document.removeEventListener('keydown', onKey, true); };
  }

  /* Blocking is a promise that the page is behind something you can see.
     A content blocker can break it from outside: Brave's cosmetic filters
     (and uBlock's cookie lists) hide a consent banner with
     `display: none !important` — often a moment after it opened — and a page
     made inert behind a panel nobody can see is a page with nothing on it that
     answers a click. So the page is blocked only while the panel actually has
     a box, and handed back the moment it stops having one. */
  function rendered(panel) {
    if (!panel.getClientRects().length) return false;
    var cs = getComputedStyle(panel);
    return cs.visibility !== 'hidden' && parseFloat(cs.opacity) !== 0;
  }

  function block(panel) {
    var release = null;
    var check = function () {
      if (!isOpen(panel)) return;
      var on = rendered(panel);
      if (on && !release) release = isolate(panel);
      else if (!on && release) { release(); release = null; }
    };
    check();
    /* A ResizeObserver hears a box disappear; the timers catch a rule that
       lands without changing any size we observe (visibility, opacity), and a
       filter that is applied after the first frames. */
    var ro = typeof ResizeObserver === 'function' ? new ResizeObserver(check) : null;
    if (ro) ro.observe(panel);
    var timer = setInterval(check, 500);
    return function () {
      if (ro) ro.disconnect();
      clearInterval(timer);
      if (release) { release(); release = null; }
    };
  }

  function focusInto(panel) {
    var first = panel.querySelector(FOCUSABLE);
    if (first) { first.focus(); return; }
    if (!panel.hasAttribute('tabindex')) panel.setAttribute('tabindex', '-1');
    panel.focus();
  }

  /* ---- one listener per panel, saying everything ------------------------

     Every state the page needs to be told about arrives as a toggle event,
     whatever opened the panel: a trigger, a click on the scrim, Escape, a
     timer, or your own code. One place to keep honest. */

  function watch(panel) {
    if (panel.__popup) return;
    panel.__popup = true;
    var placement = panel.getAttribute('data-overlay');
    var atTrigger = placement === 'trigger' || placement === 'relative';
    var blocks = panel.hasAttribute('data-popup-block');
    var release = null;
    var from = null;

    panel.addEventListener('toggle', function (e) {
      var on = e.newState === 'open';
      var triggers = triggersOf(panel);
      for (var i = 0; i < triggers.length; i++) {
        if (triggers[i].hasAttribute('aria-expanded')) triggers[i].setAttribute('aria-expanded', on ? 'true' : 'false');
      }
      if (on) {
        if (atTrigger && !anchored(panel)) { place(panel); follow(panel); }
        if (blocks) {
          from = document.activeElement;
          release = block(panel);
          focusInto(panel);
        }
        return;
      }
      if (release) { release(); release = null; }
      /* The browser puts focus back for a popover it dismissed itself — but
         not when it was sitting inside something we had just made inert,
         which a blocking panel's trigger always is while it hides. Focus is
         then still on the panel's own close button as this runs, and drifts
         to the body a moment later, so "still inside the panel" asks for it
         back too. */
      var at = document.activeElement;
      if (from && (!at || at === document.body || panel.contains(at))) {
        try { from.focus(); } catch (err) {}
      }
      from = null;
    });
  }

  /* ---- triggers ---------------------------------------------------------- */

  function manual(trigger) {
    /* The browser reads popovertarget on a button and nowhere else. */
    trigger.addEventListener('click', function () {
      var panel = panelOf(trigger);
      if (!panel) return;
      if (isOpen(panel)) hide(panel); else show(panel);
    });
    trigger.addEventListener('keydown', function (e) {
      if (e.key !== 'Enter' && e.key !== ' ' && e.key !== 'Spacebar') return;
      e.preventDefault();
      trigger.click();
    });
  }

  function hover(trigger, panel) {
    var openT, shutT;
    var inside = function () { return trigger.matches(':hover') || panel.matches(':hover'); };
    var enter = function (e) {
      /* A touch has no hover: it arrives as a tap, which is a click, which is
         the platform's own path into the panel. */
      if (e && e.pointerType && e.pointerType !== 'mouse') return;
      clearTimeout(shutT);
      openT = setTimeout(function () { show(panel); }, 90);
    };
    var leave = function () {
      clearTimeout(openT);
      shutT = setTimeout(function () { if (!inside()) hide(panel); }, 220);
    };
    trigger.addEventListener('pointerenter', enter);
    trigger.addEventListener('pointerleave', leave);
    panel.addEventListener('pointerenter', function () { clearTimeout(shutT); });
    panel.addEventListener('pointerleave', leave);
    /* Clicking a panel the pointer is already standing in would shut it under
       the cursor. A keyboard activation (detail 0) still toggles — there is no
       pointer there to have opened it. */
    trigger.addEventListener('click', function (e) {
      if (e.detail !== 0 && isOpen(panel)) e.preventDefault();
    });
  }

  /* ---- opening itself ---------------------------------------------------- */

  function afterDelay(panel) {
    var s = parseFloat(panel.getAttribute('data-popup-delay') || '0');
    setTimeout(function () { auto(panel); }, Math.max(0, s * 1000));
  }

  function atScroll(panel) {
    var want = parseFloat(panel.getAttribute('data-popup-scroll') || '50');
    var check = function () {
      var doc = document.documentElement;
      var room = (doc.scrollHeight - window.innerHeight) || 1;
      var pct = (window.scrollY / room) * 100;
      if (pct < want) return;
      window.removeEventListener('scroll', check);
      auto(panel);
    };
    window.addEventListener('scroll', check, { passive: true });
    check();
  }

  function onExit(panel) {
    /* A pointer that can leave the page at all: on a touch screen there is no
       "on the way out", and a popup that never fires is better than one that
       fires on every scroll flick. */
    if (!window.matchMedia || !matchMedia('(pointer: fine)').matches) return;
    var out = function (e) {
      if (e.relatedTarget || e.clientY > 0) return;
      document.removeEventListener('mouseout', out);
      auto(panel);
    };
    document.addEventListener('mouseout', out);
  }

  /* ---- the one thing "your own code" needs ------------------------------- */

  var api = window.sitereal || (window.sitereal = {});
  function find(id) { return typeof id === 'string' ? document.getElementById(id) : id; }
  api.openPopup = function (id) { var p = find(id); if (p) show(p); return p; };
  api.closePopup = function (id) { var p = find(id); if (p) hide(p); return p; };
  api.togglePopup = function (id) {
    var p = find(id);
    if (p) { if (isOpen(p)) hide(p); else show(p); }
    return p;
  };

  function start() {
    var panels = document.querySelectorAll('[data-overlay][popover]');
    for (var i = 0; i < panels.length; i++) watch(panels[i]);

    var triggers = document.querySelectorAll('[popovertarget]');
    for (var j = 0; j < triggers.length; j++) {
      var t = triggers[j];
      if (t.__popupTrigger) continue;
      t.__popupTrigger = true;
      var panel = panelOf(t);
      /* Which trigger a panel hangs off is whichever one you last used, not
         whichever comes first in the document. */
      t.addEventListener('pointerdown', function (e) {
        var p = panelOf(e.currentTarget);
        if (p) p.__from = e.currentTarget;
      });
      if (!t.matches('button, input')) {
        if (!t.hasAttribute('role')) t.setAttribute('role', 'button');
        if (!t.hasAttribute('tabindex')) t.setAttribute('tabindex', '0');
        manual(t);
      }
      if (panel && panel.getAttribute('data-popup-open') === 'hover') hover(t, panel);
    }

    /* And the ones that open themselves. Read off the panel, so a popup that
       is on nine pages behaves the same on all nine. */
    for (var k = 0; k < panels.length; k++) {
      var p = panels[k];
      if (p.__popupAuto) continue;
      p.__popupAuto = true;
      var how = p.getAttribute('data-popup-open');
      if (how === 'load') afterDelay(p);
      else if (how === 'scroll') atScroll(p);
      else if (how === 'exit') onExit(p);
    }
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start);
  else start();
})();
